def cloud_bts_bringup(**kwargs):
    """This keyword is used to Bring up cloud bts.
        | *Arguments* | *Default Value* | *Comments* |
        | wft_profile |  | Mandatory, details of the given profile name will be fetched from |
        |             |  | 'wft_filter.json' |
        | cloud_controller | cu | Optional |
        | package | auto | Optional, auto for automatic update. otherwise give name of the image |
        | addons_wft_profile | None | Optional, Not supported yet |

        *Examples:*

        | Cloud Bts Bringup | wft_profile=profile_name | cloud_controller  cu |

    """
    Cloud().cloud_bringup(**kwargs)


def setup_CBTS_remote_access(**kwargs):
    """
     Setup CBTS remote access

     *Usage*:
        Setup CBTS Remote Access <remote_device> <hop_list> <alias>

        ${single_hop}    controller
        @{config_list}    ${cbts}  ${ncir}
        @{config_list2}   ${cbts}  ${oam}
        @{hop_list}    ${cpif}  ${upue}

        Setup CBTS Remote Access remote_device=@{config_list}  hop_list=${single_hop} alias='double_ssh_session'
        Setup CBTS Remote Access remote_device=@{config_list2} hop_list=@{hop_list}  alias='more_than_two_hops'

     *Common*:
     | *arguments* | *default value* | *comment* | |
     | remote_device | Mandatory | Section name in test line config json file which contains |
     |   |   | details of host such as ip, username, password, prompt(if telnet). |
     | hop_list | None | In case of double ssh, give the second ssh name to hop. This can be |
     |  |  | either string in case of double ssh. If more then two ssh looping is required, |
     |  |  | Pass as list |
     | alias | Mandatory | name of execution context |
     | timeout | 30 | timeout value |

    """
    hop_list = kwargs.get("hop_list", None)
    RemoteConnection().setup_remote_access(**kwargs)
    if hop_list is not None:
        Cloud().connect_to_hop(**kwargs)


def teardown_CBTS_remote_access(**kwargs):
    """
     Teardown CBTS remote access

     *Usage*:
        Pass it similar to "Setup CBTS Remote Access" to exit from all respective hops
        connected from "Setup CBTS Remote Access"

        Teardown CBTS Remote Access <config_device> <hop_list> <alias>

        ${single_hop}    controller
        @{config_list}    ${cbts}  ${ncir}
        @{config_list2}   ${cbts}  ${oam}
        @{hop_list}    ${cpif}  ${upue}

        Teardown CBTS Remote Access config_device=@{config_list}  hop_list=${single_hop} alias='double_ssh_session'
        Teardown CBTS Remote Access config_device=@{config_list2} hop_list=@{hop_list}  alias='more_than_two_hops'

     *Common*:
     | *arguments* | *default value* | *comment* | |
     | config_device | Mandatory | Section name in test line config json file which contains |
     |   |   | details of host such as ip, username, password, prompt(if telnet). |
     | hop_list | None | In case of double ssh, give the second ssh name to hop. This can be |
     |  |  | either string in case of double ssh. If more then two ssh looping is required, |
     |  |  | Pass as list |
     | alias | Mandatory | name of execution context |
     | timeout | 30 | timeout value |

    """
    Cloud().exit_from_hop(**kwargs)
    RemoteConnection().teardown_remote_access(**kwargs)
